/**
 * Why one project of a Jira project migration failed its checks.
 */
export type JiraProjectMigrationErrorCode =
  | "duplicateProject"
  | "importDeletionRunning"
  | "invalidJql"
  | "invalidOptions"
  | "jiraAuthFailed"
  | "jiraRateLimited"
  | "jiraUnavailable"
  | "legacySyncDirection"
  | "missingCreateIssuesPermission"
  | "missingInvitePermission"
  | "missingJiraAccess"
  | "missingTeamCreationPermission"
  | "missingWebhookPermission"
  | "noMatchingIssues"
  | "projectAlreadySyncing"
  | "projectBeingImported"
  | "projectChanged"
  | "projectNotFound"
  | "projectNotReadable"
  | "projectSyncsWithAnotherTeam"
  | "teamInheritsWorkflowStatuses"
  | "teamNotAccessible"
  | "teamNotFound"
  | "teamQuotaExceeded";

/**
 * The result for one project in a Jira migration request, identified by its zero-based index. success means the requested migration is running or was already running with the same settings, not that the import finished. error explains a failed check, and the returned records let you track progress.
 */
export interface JiraProjectMigrationResult {
  __typename: "JiraProjectMigrationResult";
  /**
   * Why the project failed its checks and did not start. Null when the project is migrating.
   */
  error: JiraProjectMigrationError | null;
  /**
   * The Jira project ID. Null when the project was not found on the site.
   */
  externalId: string | null;
  /**
   * The position of the project in the input, from 0.
   */
  index: number;
  /**
   * The number of issues the import reads, counted by the checks before it started. Null when the checks did not count them: for a project that only syncs, one that failed before the count, or one that was already migrating when the checks began.
   */
  issueCount: number | null;
  /**
   * The import that the migration started, or the queued or running import of a project that was already migrating. Null for a project that only syncs, or one that failed its checks.
   */
  issueImport: IssueImport | null;
  /**
   * The Jira project that the migration wrote, or the existing one of a project that was already migrating. For a project that failed its checks, its existing Jira project, if any.
   */
  jiraProject: JiraProject | null;
  /**
   * The Jira project key, read from Jira when the checks counted the project's issues. Null when the project was not found on the site.
   */
  key: string | null;
  /**
   * The Jira project name. Null when the project was not found on the site.
   */
  name: string | null;
  /**
   * Whether the project is migrating: the migration started it, or an earlier call already migrates it as asked.
   */
  success: boolean;
}

