  resourceTypes: string[];
  /**
   * Signing secret, up to 256 characters. A secret is generated when omitted on create.
   */
  secret?: string | null;
  /**
   * UUID of the team whose events to deliver. Required unless allPublicTeams is true.
   */
  teamId?: string | null;
